DO $stage$
DECLARE payload jsonb := $payload$[{"language": "es", "slug": "huevo-katsu", "public_path": "/huevo-katsu", "title": "Huevo katsu crujiente con panko, paso a paso", "excerpt": "Aprende a hacer huevo katsu con una costra de panko y sin hervir el huevo antes. Fotos del rebozado y la fritura, con la yema bien cocinada.", "summary": "El huevo katsu es un huevo frito con una costra ligera de panko. Se monta crudo sobre papel de hornear y se cocina de uno en uno; no hace falta hervirlo ni congelarlo. Esta versión busca clara y yema firmes. Rinde 4 porciones de aperitivo con repollo fresco y tarda unos 30 minutos.", "content_html": "<h2>Sobre esta receta</h2><p>El huevo katsu es un huevo frito con una costra ligera de panko. Se monta crudo sobre papel de hornear y se cocina de uno en uno; no hace falta hervirlo ni congelarlo. Esta versión busca clara y yema firmes. Rinde 4 porciones de aperitivo con repollo fresco y tarda unos 30 minutos.</p>", "notes": "<h3>Consejos y conservación</h3><p>Usa una sartén estable, utensilios secos y papel de hornear apto según el fabricante; no dejes papel cerca de una llama. No añadas agua al aceite caliente. El tiempo de cocción contempla el calentamiento y cuatro tandas; el punto depende del tamaño del huevo. Esta receta no propone yema cruda: cocina clara y yema hasta que estén firmes. Sirve al momento; si sobran, refrigera pronto a 4 °C o menos y recalienta hasta 74 °C, aunque perderán textura. Contiene huevo y trigo. La nutrición estima 24 g de aceite absorbido en todo el lote, no los 500 ml de fritura; la absorción real varía.</p><h3>Fuentes</h3><ul><li><a href=\"https://www.okonomikitchen.com/egg-katsu/\">Okonomi Kitchen — egg katsu technique</a></li><li><a href=\"https://www.fda.gov/food/buy-store-serve-safe-food/what-you-need-know-about-egg-safety\">FDA — egg safety</a></li></ul>", "ingredients": [{"name": "huevos grandes, aproximadamente 50 g sin cáscara cada uno", "amount": "4", "unit": "unidades"}, {"name": "panko", "amount": "80", "unit": "g"}, {"name": "aceite de girasol para freír; la mayor parte queda en la sartén", "amount": "500", "unit": "ml"}, {"name": "repollo blanco", "amount": "150", "unit": "g"}, {"name": "sal", "amount": "2", "unit": "g"}], "steps": [{"title": "Prepara la mesa de trabajo", "content": "Lava, seca y corta el repollo muy fino. Prepara una rejilla sobre bandeja y papel de hornear apto para la temperatura de fritura, recortado para caber holgadamente en la sartén. No uses papel encerado.", "image_url": "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/huevo-katsu/paso-01.webp", "image_alt": "Prepara la mesa de trabajo — Huevo katsu crujiente con panko, paso a paso"}, {"title": "Coloca el huevo sobre panko", "content": "Forra un bol pequeño y poco profundo con un recorte de papel. Reparte una capa fina de panko y casca encima un huevo, manteniendo la yema entera.", "image_url": "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/huevo-katsu/paso-02.webp", "image_alt": "Coloca el huevo sobre panko — Huevo katsu crujiente con panko, paso a paso"}, {"title": "Cubre sin romper la yema", "content": "Añade una pizca de la sal y cubre suavemente todo el huevo con más panko. Reparte el panko y la sal disponibles entre los huevos; no presiones la yema.", "image_url": "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/huevo-katsu/paso-03.webp", "image_alt": "Cubre sin romper la yema — Huevo katsu crujiente con panko, paso a paso"}, {"title": "Calienta el aceite", "content": "En una sartén pequeña y profunda de unos 18 cm, calienta el aceite hasta 170 °C, con unos 2 cm de profundidad. Usa termómetro, deja espacio libre y evita que humee.", "image_url": "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/huevo-katsu/paso-04.webp", "image_alt": "Calienta el aceite — Huevo katsu crujiente con panko, paso a paso"}, {"title": "Empieza la fritura", "content": "Sostén el papel con una espumadera larga y baja el huevo cerca del aceite, despacio y sin salpicar. Mantén el papel dentro de la sartén, lejos de llamas. Baña la superficie con un poco de aceite caliente hasta que cuaje.", "image_url": "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/huevo-katsu/paso-05.webp", "image_alt": "Empieza la fritura — Huevo katsu crujiente con panko, paso a paso"}, {"title": "Retira el papel y termina", "content": "Cuando el huevo se sostenga, retira el papel con pinzas largas, voltea el huevo y cocina unos 3–4 minutos en total, ajustando el fuego. La clara y la yema deben quedar firmes; si falta cocción, continúa a fuego más suave.", "image_url": "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/huevo-katsu/paso-06.webp", "image_alt": "Retira el papel y termina — Huevo katsu crujiente con panko, paso a paso"}, {"title": "Escurre y repite", "content": "Pasa el huevo a la rejilla. Repite de uno en uno con los demás, recuperando los 170 °C entre tandas. Desecha el panko que haya tocado huevo crudo y no se haya cocinado.", "image_url": "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/huevo-katsu/paso-07.webp", "image_alt": "Escurre y repite — Huevo katsu crujiente con panko, paso a paso"}, {"title": "Sirve recién hecho", "content": "Sirve cada huevo con parte del repollo. Corta con cuidado para comprobar el interior y disfruta mientras la costra está crujiente. Si la yema aún está líquida, vuelve a cocinarlo antes de servir.", "image_url": "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/huevo-katsu/paso-08.webp", "image_alt": "Sirve recién hecho — Huevo katsu crujiente con panko, paso a paso"}], "category": "Entrantes y aperitivos", "course": "Entradas", "cuisine": "Inspiración japonesa", "difficulty": "Fácil", "prep_time_minutes": 10, "cook_time_minutes": 20, "total_time_minutes": 30, "servings": 4, "image_url": "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/huevo-katsu/portada.webp", "gallery": [{"url": "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/huevo-katsu/portada.webp", "alt": "Huevo katsu dorado cortado para mostrar clara y yema firmes, junto a repollo fino"}], "video_urls": [], "keywords": ["huevo katsu", "egg katsu", "huevo con panko", "tamago katsu"], "nutrition": {"calories": 212.9, "protein_g": 9.4, "carbs_g": 16.9, "fat_g": 11.9, "estimated": true, "serving_size": "1 huevo katsu con una cuarta parte del repollo", "note": "Estimación por ración; los productos y el rendimiento pueden cambiar los valores.", "source": "Cálculo editorial con perfiles genéricos de ingredientes", "method": "Sum ingredient edible weights × generic per-100-g profiles; divide by recipe servings. See source JSON nutrition_calculation."}, "seo": {"title": "Huevo katsu crujiente con panko, paso a paso", "description": "Aprende a hacer huevo katsu con una costra de panko y sin hervir el huevo antes. Fotos del rebozado y la fritura, con la yema bien cocinada.", "author": "Néstor Bastidas", "image_alt": "Huevo katsu dorado cortado para mostrar clara y yema firmes, junto a repollo fino", "image_variants": ["https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/huevo-katsu/portada-1x1.webp", "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/huevo-katsu/portada-4x3.webp", "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/huevo-katsu/portada-16x9.webp"], "faq": [{"q": "¿Se hierve el huevo antes?", "a": "No. Se coloca crudo sobre panko y papel de hornear, se cubre y se fríe con cuidado. No es un huevo cocido empanado."}, {"q": "¿Puede quedar la yema líquida?", "a": "Esta versión se cocina hasta tener clara y yema firmes. No indicamos una cocción corta para dejar la yema cruda."}, {"q": "¿Por qué no sumar todo el aceite a la nutrición?", "a": "Los 500 ml son el medio de fritura y no se consumen completos. El cálculo usa una absorción orientativa de 24 g para el lote, que puede variar."}], "additional_time_minutes": 0}, "published": false, "editorial_status": "draft"}, {"language": "en", "slug": "crispy-egg-katsu", "public_path": "/en/crispy-egg-katsu", "title": "Crispy Egg Katsu with Panko, Step by Step", "excerpt": "Make egg katsu with a crisp panko coating, without boiling the egg first. Step photos explain coating and frying with a fully cooked yolk.", "summary": "Egg katsu is a fried egg with a light panko crust. Assemble it raw on baking parchment and fry one at a time; no boiling or freezing is needed. This version cooks both white and yolk until firm. Makes 4 appetizer servings with fresh cabbage in about 30 minutes.", "content_html": "<h2>About this recipe</h2><p>Egg katsu is a fried egg with a light panko crust. Assemble it raw on baking parchment and fry one at a time; no boiling or freezing is needed. This version cooks both white and yolk until firm. Makes 4 appetizer servings with fresh cabbage in about 30 minutes.</p>", "notes": "<h3>Tips and storage</h3><p>Use a stable pan, dry utensils and baking parchment rated by its manufacturer for the temperature; keep paper away from flames. Never add water to hot oil. Cooking time includes heating and four batches; egg size affects doneness. This recipe cooks both white and yolk until firm. Serve promptly; refrigerate leftovers soon at 4 °C / 40 °F or below and reheat to 74 °C / 165 °F, though crispness will decline. Contains egg and wheat. Nutrition assumes 24 g of absorbed oil across the batch, not all 500 ml of frying oil; actual absorption varies.</p><h3>Sources</h3><ul><li><a href=\"https://www.okonomikitchen.com/egg-katsu/\">Okonomi Kitchen — egg katsu technique</a></li><li><a href=\"https://www.fda.gov/food/buy-store-serve-safe-food/what-you-need-know-about-egg-safety\">FDA — egg safety</a></li></ul>", "ingredients": [{"name": "large eggs, about 50 g each without shell", "amount": "4", "unit": "pieces"}, {"name": "panko breadcrumbs", "amount": "80", "unit": "g"}, {"name": "sunflower oil for frying; most stays in the pan", "amount": "500", "unit": "ml"}, {"name": "white cabbage", "amount": "150", "unit": "g"}, {"name": "salt", "amount": "2", "unit": "g"}], "steps": [{"title": "Prepare the workspace", "content": "Wash, dry and finely shred the cabbage. Set a rack over a tray. Cut frying-temperature-rated baking parchment small enough to fit well inside the pan. Do not use wax paper.", "image_url": "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/huevo-katsu/paso-01.webp", "image_alt": "Prepare the workspace — Crispy Egg Katsu with Panko, Step by Step"}, {"title": "Set the egg on panko", "content": "Line a small shallow bowl with a parchment square. Add a thin panko layer and crack one egg onto it, keeping the yolk intact.", "image_url": "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/huevo-katsu/paso-02.webp", "image_alt": "Set the egg on panko — Crispy Egg Katsu with Panko, Step by Step"}, {"title": "Cover without breaking the yolk", "content": "Add a pinch of the salt and gently cover the entire egg with more panko. Divide the available panko and salt among the eggs; do not press the yolk.", "image_url": "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/huevo-katsu/paso-03.webp", "image_alt": "Cover without breaking the yolk — Crispy Egg Katsu with Panko, Step by Step"}, {"title": "Heat the oil", "content": "Heat the oil to 170 °C / 340 °F in a small deep pan about 18 cm / 7 inches across, with roughly 2 cm of oil. Use a thermometer, leave headroom and avoid smoking.", "image_url": "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/huevo-katsu/paso-04.webp", "image_alt": "Heat the oil — Crispy Egg Katsu with Panko, Step by Step"}, {"title": "Begin frying", "content": "Support the paper with a long slotted spoon and slowly lower the egg close to the oil without splashing. Keep paper inside the pan and away from flames. Spoon a little hot oil over the top until it sets.", "image_url": "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/huevo-katsu/paso-05.webp", "image_alt": "Begin frying — Crispy Egg Katsu with Panko, Step by Step"}, {"title": "Remove paper and finish", "content": "Once the egg holds together, remove the paper with long tongs and turn the egg. Fry for roughly 3–4 minutes total, adjusting heat. White and yolk must be firm; continue over gentler heat if needed.", "image_url": "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/huevo-katsu/paso-06.webp", "image_alt": "Remove paper and finish — Crispy Egg Katsu with Panko, Step by Step"}, {"title": "Drain and repeat", "content": "Transfer to the rack. Repeat one egg at a time, bringing oil back to 170 °C / 340 °F between batches. Discard any uncooked panko that contacted raw egg.", "image_url": "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/huevo-katsu/paso-07.webp", "image_alt": "Drain and repeat — Crispy Egg Katsu with Panko, Step by Step"}, {"title": "Serve immediately", "content": "Serve each egg with a share of the cabbage. Cut carefully to check the center and enjoy while crisp. If the yolk is still liquid, cook it further before serving.", "image_url": "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/huevo-katsu/paso-08.webp", "image_alt": "Serve immediately — Crispy Egg Katsu with Panko, Step by Step"}], "category": "Starters & appetizers", "course": "Appetizers", "cuisine": "Japanese inspired", "difficulty": "Easy", "prep_time_minutes": 10, "cook_time_minutes": 20, "total_time_minutes": 30, "servings": 4, "image_url": "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/huevo-katsu/portada.webp", "gallery": [{"url": "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/huevo-katsu/portada.webp", "alt": "Golden egg katsu cut to show firm white and yolk with finely shredded cabbage"}], "video_urls": [], "keywords": ["egg katsu", "crispy egg katsu", "panko fried egg", "tamago katsu"], "nutrition": {"calories": 212.9, "protein_g": 9.4, "carbs_g": 16.9, "fat_g": 11.9, "estimated": true, "serving_size": "1 egg katsu with one-quarter of the cabbage", "note": "Estimated per serving; products and yield can change these values.", "source": "Editorial calculation using generic ingredient profiles", "method": "Sum ingredient edible weights × generic per-100-g profiles; divide by recipe servings. See source JSON nutrition_calculation."}, "seo": {"title": "Crispy Egg Katsu with Panko, Step by Step", "description": "Make egg katsu with a crisp panko coating, without boiling the egg first. Step photos explain coating and frying with a fully cooked yolk.", "author": "Néstor Bastidas", "image_alt": "Golden egg katsu cut to show firm white and yolk with finely shredded cabbage", "image_variants": ["https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/huevo-katsu/portada-1x1.webp", "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/huevo-katsu/portada-4x3.webp", "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/huevo-katsu/portada-16x9.webp"], "faq": [{"q": "Do I boil the egg first?", "a": "No. Assemble the raw egg on panko and parchment, cover with more crumbs and fry carefully. It is not a breaded hard-boiled egg."}, {"q": "Can the yolk be runny?", "a": "This version cooks both white and yolk until firm. It does not give a short frying time for a raw yolk."}, {"q": "Why is not all the oil counted in nutrition?", "a": "The 500 ml is the frying medium, not the amount eaten. The estimate assumes 24 g absorbed by the batch, which can vary."}], "additional_time_minutes": 0}, "published": false, "editorial_status": "draft"}, {"language": "de", "slug": "ei-katsu-panko", "public_path": "/de/ei-katsu-panko", "title": "Knuspriges Ei-Katsu mit Panko Schritt für Schritt", "excerpt": "Ei-Katsu mit knuspriger Panko-Kruste, ohne das Ei vorzukochen. Schrittbilder zeigen Panieren und Frittieren mit vollständig gegartem Eigelb.", "summary": "Ei-Katsu ist ein Spiegelei mit leichter Panko-Kruste. Es wird roh auf Backpapier vorbereitet und einzeln frittiert, ohne Vorkochen oder Einfrieren. In dieser Variante werden Eiweiß und Eigelb fest gegart. Für 4 Vorspeisenportionen mit frischem Kohl in etwa 30 Minuten.", "content_html": "<h2>Über dieses Rezept</h2><p>Ei-Katsu ist ein Spiegelei mit leichter Panko-Kruste. Es wird roh auf Backpapier vorbereitet und einzeln frittiert, ohne Vorkochen oder Einfrieren. In dieser Variante werden Eiweiß und Eigelb fest gegart. Für 4 Vorspeisenportionen mit frischem Kohl in etwa 30 Minuten.</p>", "notes": "<h3>Tipps und Aufbewahrung</h3><p>Eine stabile Pfanne, trockene Geräte und laut Hersteller geeignetes Backpapier verwenden; Papier von Flammen fernhalten. Kein Wasser in heißes Öl geben. Die Garzeit umfasst Aufheizen und vier Durchgänge; die Eiergröße beeinflusst den Garpunkt. Eiweiß und Eigelb werden hier fest gegart. Sofort servieren; Reste zügig bei höchstens 4 °C kühlen und auf 74 °C erhitzen, wobei die Kruste weicher wird. Enthält Ei und Weizen. Die Nährwertschätzung rechnet mit insgesamt 24 g aufgenommenem Öl, nicht mit allen 500 ml Frittieröl; die tatsächliche Aufnahme schwankt.</p><h3>Quellen</h3><ul><li><a href=\"https://www.okonomikitchen.com/egg-katsu/\">Okonomi Kitchen — egg katsu technique</a></li><li><a href=\"https://www.fda.gov/food/buy-store-serve-safe-food/what-you-need-know-about-egg-safety\">FDA — egg safety</a></li></ul>", "ingredients": [{"name": "große Eier, ohne Schale jeweils etwa 50 g", "amount": "4", "unit": "Stück"}, {"name": "Panko", "amount": "80", "unit": "g"}, {"name": "Sonnenblumenöl zum Frittieren; der größte Teil bleibt in der Pfanne", "amount": "500", "unit": "ml"}, {"name": "Weißkohl", "amount": "150", "unit": "g"}, {"name": "Salz", "amount": "2", "unit": "g"}], "steps": [{"title": "Arbeitsplatz vorbereiten", "content": "Kohl waschen, trocknen und fein hobeln. Ein Gitter über ein Blech setzen. Für die Frittiertemperatur geeignetes Backpapier so zuschneiden, dass es gut in die Pfanne passt. Kein Wachspapier verwenden.", "image_url": "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/huevo-katsu/paso-01.webp", "image_alt": "Arbeitsplatz vorbereiten — Knuspriges Ei-Katsu mit Panko Schritt für Schritt"}, {"title": "Ei auf Panko setzen", "content": "Eine kleine flache Schüssel mit einem Papierstück auslegen. Eine dünne Schicht Panko einstreuen und ein Ei darauf aufschlagen, ohne das Eigelb zu verletzen.", "image_url": "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/huevo-katsu/paso-02.webp", "image_alt": "Ei auf Panko setzen — Knuspriges Ei-Katsu mit Panko Schritt für Schritt"}, {"title": "Ei vorsichtig bedecken", "content": "Etwas vom Salz darübergeben und das gesamte Ei locker mit Panko bedecken. Panko und Salz auf die Eier verteilen; nicht auf das Eigelb drücken.", "image_url": "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/huevo-katsu/paso-03.webp", "image_alt": "Ei vorsichtig bedecken — Knuspriges Ei-Katsu mit Panko Schritt für Schritt"}, {"title": "Öl erhitzen", "content": "Öl in einer kleinen tiefen Pfanne von etwa 18 cm Durchmesser auf 170 °C erhitzen, ungefähr 2 cm hoch. Thermometer benutzen, Rand frei lassen und Rauch vermeiden.", "image_url": "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/huevo-katsu/paso-04.webp", "image_alt": "Öl erhitzen — Knuspriges Ei-Katsu mit Panko Schritt für Schritt"}, {"title": "Frittieren beginnen", "content": "Das Papier mit einer langen Schaumkelle stützen und das Ei dicht über dem Öl langsam absenken, ohne Spritzer. Papier innerhalb der Pfanne und fern von Flammen halten. Oben mit etwas heißem Öl begießen, bis das Ei fest wird.", "image_url": "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/huevo-katsu/paso-05.webp", "image_alt": "Frittieren beginnen — Knuspriges Ei-Katsu mit Panko Schritt für Schritt"}, {"title": "Papier entfernen und fertig garen", "content": "Sobald das Ei zusammenhält, Papier mit langer Zange entfernen und Ei wenden. Insgesamt etwa 3–4 Minuten frittieren, Hitze anpassen. Eiweiß und Eigelb müssen fest sein; bei Bedarf bei milderer Hitze weitergaren.", "image_url": "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/huevo-katsu/paso-06.webp", "image_alt": "Papier entfernen und fertig garen — Knuspriges Ei-Katsu mit Panko Schritt für Schritt"}, {"title": "Abtropfen lassen und wiederholen", "content": "Ei auf das Gitter legen. Übrige Eier einzeln garen und das Öl dazwischen wieder auf 170 °C bringen. Ungegarte Pankoreste mit Kontakt zu rohem Ei entsorgen.", "image_url": "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/huevo-katsu/paso-07.webp", "image_alt": "Abtropfen lassen und wiederholen — Knuspriges Ei-Katsu mit Panko Schritt für Schritt"}, {"title": "Sofort servieren", "content": "Jedes Ei mit einem Anteil Kohl servieren. Vorsichtig aufschneiden und den Kern prüfen. Ist das Eigelb noch flüssig, vor dem Servieren weitergaren.", "image_url": "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/huevo-katsu/paso-08.webp", "image_alt": "Sofort servieren — Knuspriges Ei-Katsu mit Panko Schritt für Schritt"}], "category": "Vorspeisen", "course": "Vorspeisen", "cuisine": "Japanisch inspiriert", "difficulty": "Einfach", "prep_time_minutes": 10, "cook_time_minutes": 20, "total_time_minutes": 30, "servings": 4, "image_url": "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/huevo-katsu/portada.webp", "gallery": [{"url": "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/huevo-katsu/portada.webp", "alt": "Goldenes Ei-Katsu mit festem Eiweiß und Eigelb neben fein gehobeltem Kohl"}], "video_urls": [], "keywords": ["Ei Katsu", "Egg Katsu", "Ei mit Panko", "Tamago Katsu"], "nutrition": {"calories": 212.9, "protein_g": 9.4, "carbs_g": 16.9, "fat_g": 11.9, "estimated": true, "serving_size": "1 Ei-Katsu mit einem Viertel des Kohls", "note": "Schätzwerte pro Portion; Produkte und Ausbeute können die Werte verändern.", "source": "Redaktionelle Berechnung mit allgemeinen Zutatenprofilen", "method": "Sum ingredient edible weights × generic per-100-g profiles; divide by recipe servings. See source JSON nutrition_calculation."}, "seo": {"title": "Knuspriges Ei-Katsu mit Panko Schritt für Schritt", "description": "Ei-Katsu mit knuspriger Panko-Kruste, ohne das Ei vorzukochen. Schrittbilder zeigen Panieren und Frittieren mit vollständig gegartem Eigelb.", "author": "Néstor Bastidas", "image_alt": "Goldenes Ei-Katsu mit festem Eiweiß und Eigelb neben fein gehobeltem Kohl", "image_variants": ["https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/huevo-katsu/portada-1x1.webp", "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/huevo-katsu/portada-4x3.webp", "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/huevo-katsu/portada-16x9.webp"], "faq": [{"q": "Wird das Ei vorgekocht?", "a": "Nein. Das rohe Ei wird auf Panko und Backpapier gesetzt, mit Bröseln bedeckt und vorsichtig frittiert."}, {"q": "Darf das Eigelb flüssig bleiben?", "a": "Diese Variante gart Eiweiß und Eigelb fest. Eine verkürzte Garzeit für rohes Eigelb ist nicht vorgesehen."}, {"q": "Warum wird nicht das gesamte Öl berechnet?", "a": "Die 500 ml dienen zum Frittieren und werden nicht vollständig gegessen. Geschätzt werden 24 g Ölaufnahme für die gesamte Menge."}], "additional_time_minutes": 0}, "published": false, "editorial_status": "draft"}, {"language": "fr", "slug": "oeuf-katsu-panko", "public_path": "/fr/oeuf-katsu-panko", "title": "Œuf katsu croustillant au panko, étape par étape", "excerpt": "Un œuf katsu à la croûte de panko sans précuisson à l’eau. Photos de la panure et de la friture pour obtenir un jaune bien cuit.", "summary": "L’œuf katsu est un œuf frit dans une légère croûte de panko. Il se prépare cru sur du papier cuisson et se frit un à un, sans le faire bouillir ni le congeler. Cette version donne un blanc et un jaune fermes. Pour 4 portions apéritives avec du chou, en 30 minutes environ.", "content_html": "<h2>À propos de cette recette</h2><p>L’œuf katsu est un œuf frit dans une légère croûte de panko. Il se prépare cru sur du papier cuisson et se frit un à un, sans le faire bouillir ni le congeler. Cette version donne un blanc et un jaune fermes. Pour 4 portions apéritives avec du chou, en 30 minutes environ.</p>", "notes": "<h3>Conseils et conservation</h3><p>Utilisez une poêle stable, des ustensiles secs et du papier cuisson adapté selon le fabricant ; éloignez-le des flammes. Ne versez jamais d’eau dans l’huile chaude. La durée comprend le chauffage et quatre cuissons ; la taille des œufs change le temps nécessaire. Ici, blanc et jaune doivent être fermes. Servez aussitôt ; réfrigérez rapidement les restes à 4 °C maximum et réchauffez à 74 °C, avec une perte de croustillant. Contient œuf et blé. La nutrition suppose 24 g d’huile absorbée pour le lot, et non les 500 ml utilisés pour frire ; l’absorption varie.</p><h3>Sources</h3><ul><li><a href=\"https://www.okonomikitchen.com/egg-katsu/\">Okonomi Kitchen — egg katsu technique</a></li><li><a href=\"https://www.fda.gov/food/buy-store-serve-safe-food/what-you-need-know-about-egg-safety\">FDA — egg safety</a></li></ul>", "ingredients": [{"name": "gros œufs, environ 50 g chacun sans coquille", "amount": "4", "unit": "unités"}, {"name": "panko", "amount": "80", "unit": "g"}, {"name": "huile de tournesol pour la friture ; la majeure partie reste dans la poêle", "amount": "500", "unit": "ml"}, {"name": "chou blanc", "amount": "150", "unit": "g"}, {"name": "sel", "amount": "2", "unit": "g"}], "steps": [{"title": "Préparez le plan de travail", "content": "Lavez, séchez et émincez finement le chou. Posez une grille sur une plaque. Découpez du papier cuisson adapté à la température de friture pour qu’il tienne largement dans la poêle. Pas de papier ciré.", "image_url": "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/huevo-katsu/paso-01.webp", "image_alt": "Préparez le plan de travail — Œuf katsu croustillant au panko, étape par étape"}, {"title": "Posez l’œuf sur le panko", "content": "Tapissez un petit bol peu profond d’un carré de papier. Mettez une fine couche de panko puis cassez un œuf dessus sans percer le jaune.", "image_url": "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/huevo-katsu/paso-02.webp", "image_alt": "Posez l’œuf sur le panko — Œuf katsu croustillant au panko, étape par étape"}, {"title": "Recouvrez délicatement", "content": "Ajoutez une pincée du sel et couvrez tout l’œuf de panko sans appuyer sur le jaune. Répartissez le panko et le sel disponibles entre les œufs.", "image_url": "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/huevo-katsu/paso-03.webp", "image_alt": "Recouvrez délicatement — Œuf katsu croustillant au panko, étape par étape"}, {"title": "Chauffez l’huile", "content": "Portez l’huile à 170 °C dans une petite poêle profonde d’environ 18 cm, sur environ 2 cm de hauteur. Utilisez un thermomètre, laissez de la marge et évitez la fumée.", "image_url": "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/huevo-katsu/paso-04.webp", "image_alt": "Chauffez l’huile — Œuf katsu croustillant au panko, étape par étape"}, {"title": "Commencez la friture", "content": "Soutenez le papier avec une longue écumoire et descendez doucement l’œuf près de l’huile, sans éclabousser. Gardez le papier dans la poêle, loin des flammes. Arrosez le dessus d’un peu d’huile chaude jusqu’à ce qu’il prenne.", "image_url": "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/huevo-katsu/paso-05.webp", "image_alt": "Commencez la friture — Œuf katsu croustillant au panko, étape par étape"}, {"title": "Retirez le papier et terminez", "content": "Lorsque l’œuf se tient, retirez le papier avec une longue pince et retournez-le. Comptez environ 3–4 minutes au total, en réglant le feu. Blanc et jaune doivent être fermes ; poursuivez plus doucement si besoin.", "image_url": "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/huevo-katsu/paso-06.webp", "image_alt": "Retirez le papier et terminez — Œuf katsu croustillant au panko, étape par étape"}, {"title": "Égouttez et recommencez", "content": "Posez sur la grille. Faites cuire les autres un à un, en ramenant l’huile à 170 °C entre les cuissons. Jetez le panko non cuit ayant touché l’œuf cru.", "image_url": "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/huevo-katsu/paso-07.webp", "image_alt": "Égouttez et recommencez — Œuf katsu croustillant au panko, étape par étape"}, {"title": "Servez immédiatement", "content": "Servez chaque œuf avec une part du chou. Coupez prudemment pour vérifier le cœur. Si le jaune est encore liquide, poursuivez la cuisson avant de servir.", "image_url": "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/huevo-katsu/paso-08.webp", "image_alt": "Servez immédiatement — Œuf katsu croustillant au panko, étape par étape"}], "category": "Entrées et apéritifs", "course": "Entrées", "cuisine": "Inspiration japonaise", "difficulty": "Facile", "prep_time_minutes": 10, "cook_time_minutes": 20, "total_time_minutes": 30, "servings": 4, "image_url": "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/huevo-katsu/portada.webp", "gallery": [{"url": "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/huevo-katsu/portada.webp", "alt": "Œuf katsu doré ouvert sur un blanc et un jaune fermes, avec du chou finement émincé"}], "video_urls": [], "keywords": ["œuf katsu", "egg katsu", "œuf pané panko", "tamago katsu"], "nutrition": {"calories": 212.9, "protein_g": 9.4, "carbs_g": 16.9, "fat_g": 11.9, "estimated": true, "serving_size": "1 œuf katsu avec un quart du chou", "note": "Estimation par portion ; les produits et le rendement peuvent modifier ces valeurs.", "source": "Calcul éditorial à partir de profils génériques des ingrédients", "method": "Sum ingredient edible weights × generic per-100-g profiles; divide by recipe servings. See source JSON nutrition_calculation."}, "seo": {"title": "Œuf katsu croustillant au panko, étape par étape", "description": "Un œuf katsu à la croûte de panko sans précuisson à l’eau. Photos de la panure et de la friture pour obtenir un jaune bien cuit.", "author": "Néstor Bastidas", "image_alt": "Œuf katsu doré ouvert sur un blanc et un jaune fermes, avec du chou finement émincé", "image_variants": ["https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/huevo-katsu/portada-1x1.webp", "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/huevo-katsu/portada-4x3.webp", "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/huevo-katsu/portada-16x9.webp"], "faq": [{"q": "Faut-il cuire l’œuf à l’eau avant ?", "a": "Non. Posez l’œuf cru sur le panko et le papier cuisson, recouvrez-le puis faites-le frire délicatement."}, {"q": "Le jaune peut-il rester coulant ?", "a": "Cette version cuit le blanc et le jaune jusqu’à ce qu’ils soient fermes. Elle ne propose pas de friture courte pour un jaune cru."}, {"q": "Pourquoi ne pas compter toute l’huile ?", "a": "Les 500 ml servent de bain de friture et ne sont pas entièrement consommés. Le calcul suppose 24 g absorbés pour le lot."}], "additional_time_minutes": 0}, "published": false, "editorial_status": "draft"}, {"language": "it", "slug": "uovo-katsu-panko", "public_path": "/it/uovo-katsu-panko", "title": "Uovo katsu croccante con panko, passo dopo passo", "excerpt": "Prepara l’uovo katsu con crosta di panko senza prima lessarlo. Foto della panatura e della frittura, con tuorlo completamente cotto.", "summary": "L’uovo katsu è un uovo fritto con una leggera crosta di panko. Si prepara crudo sulla carta da forno e si frigge uno alla volta, senza lessarlo né congelarlo. Qui albume e tuorlo vengono cotti fino a rassodarsi. Per 4 porzioni da antipasto con cavolo, in circa 30 minuti.", "content_html": "<h2>Informazioni sulla ricetta</h2><p>L’uovo katsu è un uovo fritto con una leggera crosta di panko. Si prepara crudo sulla carta da forno e si frigge uno alla volta, senza lessarlo né congelarlo. Qui albume e tuorlo vengono cotti fino a rassodarsi. Per 4 porzioni da antipasto con cavolo, in circa 30 minuti.</p>", "notes": "<h3>Consigli e conservazione</h3><p>Usa una padella stabile, utensili asciutti e carta da forno adatta secondo il produttore; tienila lontana dalle fiamme. Non aggiungere acqua all’olio caldo. Il tempo comprende riscaldamento e quattro cotture; la dimensione delle uova influisce. Qui albume e tuorlo devono essere sodi. Servi subito; conserva rapidamente gli avanzi a non più di 4 °C e riscalda a 74 °C, sapendo che la crosta si ammorbidisce. Contiene uovo e frumento. La nutrizione stima 24 g di olio assorbito nel lotto, non tutti i 500 ml usati per friggere; l’assorbimento varia.</p><h3>Fonti</h3><ul><li><a href=\"https://www.okonomikitchen.com/egg-katsu/\">Okonomi Kitchen — egg katsu technique</a></li><li><a href=\"https://www.fda.gov/food/buy-store-serve-safe-food/what-you-need-know-about-egg-safety\">FDA — egg safety</a></li></ul>", "ingredients": [{"name": "uova grandi, circa 50 g ciascuna senza guscio", "amount": "4", "unit": "unità"}, {"name": "panko", "amount": "80", "unit": "g"}, {"name": "olio di girasole per friggere; la maggior parte resta in padella", "amount": "500", "unit": "ml"}, {"name": "cavolo cappuccio bianco", "amount": "150", "unit": "g"}, {"name": "sale", "amount": "2", "unit": "g"}], "steps": [{"title": "Prepara il piano di lavoro", "content": "Lava, asciuga e affetta finemente il cavolo. Sistema una griglia su un vassoio. Ritaglia carta da forno adatta alla temperatura di frittura, abbastanza piccola da entrare comodamente in padella. Non usare carta cerata.", "image_url": "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/huevo-katsu/paso-01.webp", "image_alt": "Prepara il piano di lavoro — Uovo katsu croccante con panko, passo dopo passo"}, {"title": "Appoggia l’uovo sul panko", "content": "Rivesti una ciotolina bassa con un quadrato di carta. Distribuisci un sottile strato di panko e rompi sopra un uovo mantenendo intero il tuorlo.", "image_url": "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/huevo-katsu/paso-02.webp", "image_alt": "Appoggia l’uovo sul panko — Uovo katsu croccante con panko, passo dopo passo"}, {"title": "Copri senza rompere il tuorlo", "content": "Aggiungi un pizzico del sale e copri delicatamente tutto l’uovo con altro panko. Dividi panko e sale disponibili fra le uova, senza premere sul tuorlo.", "image_url": "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/huevo-katsu/paso-03.webp", "image_alt": "Copri senza rompere il tuorlo — Uovo katsu croccante con panko, passo dopo passo"}, {"title": "Scalda l’olio", "content": "Porta l’olio a 170 °C in una padella piccola e profonda di circa 18 cm, con uno strato di circa 2 cm. Usa un termometro, lascia spazio libero ed evita il fumo.", "image_url": "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/huevo-katsu/paso-04.webp", "image_alt": "Scalda l’olio — Uovo katsu croccante con panko, passo dopo passo"}, {"title": "Inizia a friggere", "content": "Sostieni la carta con una schiumarola lunga e abbassa lentamente l’uovo vicino all’olio senza schizzi. Tieni la carta dentro la padella e lontana dalle fiamme. Versa poco olio caldo sulla superficie finché si rassoda.", "image_url": "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/huevo-katsu/paso-05.webp", "image_alt": "Inizia a friggere — Uovo katsu croccante con panko, passo dopo passo"}, {"title": "Togli la carta e completa", "content": "Quando l’uovo si sostiene, sfila la carta con pinze lunghe e giralo. Friggi per circa 3–4 minuti totali, regolando il calore. Albume e tuorlo devono essere sodi; se serve continua a fuoco più dolce.", "image_url": "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/huevo-katsu/paso-06.webp", "image_alt": "Togli la carta e completa — Uovo katsu croccante con panko, passo dopo passo"}, {"title": "Scola e ripeti", "content": "Trasferisci sulla griglia. Cuoci le altre uova una alla volta, riportando l’olio a 170 °C fra le cotture. Scarta il panko non cotto entrato a contatto con uovo crudo.", "image_url": "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/huevo-katsu/paso-07.webp", "image_alt": "Scola e ripeti — Uovo katsu croccante con panko, passo dopo passo"}, {"title": "Servi subito", "content": "Servi ogni uovo con parte del cavolo. Taglia con cautela per controllare il centro. Se il tuorlo è ancora liquido, prosegui la cottura prima di servire.", "image_url": "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/huevo-katsu/paso-08.webp", "image_alt": "Servi subito — Uovo katsu croccante con panko, passo dopo passo"}], "category": "Antipasti", "course": "Antipasti", "cuisine": "Ispirazione giapponese", "difficulty": "Facile", "prep_time_minutes": 10, "cook_time_minutes": 20, "total_time_minutes": 30, "servings": 4, "image_url": "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/huevo-katsu/portada.webp", "gallery": [{"url": "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/huevo-katsu/portada.webp", "alt": "Uovo katsu dorato tagliato con albume e tuorlo sodi, accanto a cavolo fine"}], "video_urls": [], "keywords": ["uovo katsu", "egg katsu", "uovo panko", "tamago katsu"], "nutrition": {"calories": 212.9, "protein_g": 9.4, "carbs_g": 16.9, "fat_g": 11.9, "estimated": true, "serving_size": "1 uovo katsu con un quarto del cavolo", "note": "Stima per porzione; prodotti e resa possono modificare questi valori.", "source": "Calcolo redazionale con profili generici degli ingredienti", "method": "Sum ingredient edible weights × generic per-100-g profiles; divide by recipe servings. See source JSON nutrition_calculation."}, "seo": {"title": "Uovo katsu croccante con panko, passo dopo passo", "description": "Prepara l’uovo katsu con crosta di panko senza prima lessarlo. Foto della panatura e della frittura, con tuorlo completamente cotto.", "author": "Néstor Bastidas", "image_alt": "Uovo katsu dorato tagliato con albume e tuorlo sodi, accanto a cavolo fine", "image_variants": ["https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/huevo-katsu/portada-1x1.webp", "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/huevo-katsu/portada-4x3.webp", "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/huevo-katsu/portada-16x9.webp"], "faq": [{"q": "Devo lessare prima l’uovo?", "a": "No. L’uovo crudo si posa su panko e carta da forno, si copre e si frigge con cautela."}, {"q": "Il tuorlo può rimanere liquido?", "a": "Questa versione cuoce albume e tuorlo fino a rassodarli. Non prevede una cottura breve per un tuorlo crudo."}, {"q": "Perché non contare tutto l’olio?", "a": "I 500 ml servono alla frittura e non vengono consumati interamente. La stima considera 24 g assorbiti nel lotto."}], "additional_time_minutes": 0}, "published": false, "editorial_status": "draft"}, {"language": "ja", "slug": "tamago-katsu-panko", "public_path": "/ja/tamago-katsu-panko", "title": "卵カツの作り方｜ゆでずに作るサクサクのパン粉衣", "excerpt": "生卵をパン粉にのせて揚げる卵カツ。下ゆで不要で、衣の付け方と揚げ方を写真で紹介。黄身までしっかり火を通すレシピです。", "summary": "卵カツは、卵を軽いパン粉衣で包んで揚げる料理です。生のままオーブン用ペーパーにのせ、ひとつずつ揚げるので、下ゆでや冷凍は不要です。この配合では白身と黄身の両方にしっかり火を通します。キャベツを添えた前菜4人分、約30分です。", "content_html": "<h2>このレシピについて</h2><p>卵カツは、卵を軽いパン粉衣で包んで揚げる料理です。生のままオーブン用ペーパーにのせ、ひとつずつ揚げるので、下ゆでや冷凍は不要です。この配合では白身と黄身の両方にしっかり火を通します。キャベツを添えた前菜4人分、約30分です。</p>", "notes": "<h3>コツと保存方法</h3><p>安定した鍋、乾いた道具、メーカーが温度に対応するとしているオーブン用ペーパーを使い、紙を炎に近づけないでください。熱い油に水を入れません。加熱時間には油を温める時間と4回の揚げ作業を含み、卵の大きさで変わります。このレシピでは白身と黄身を固まるまで加熱します。できたてを食べ、残りは速やかに4 °C以下で冷蔵し、再加熱は74 °Cまで行いますが、衣の食感は落ちます。卵、小麦を含みます。栄養計算は全量で油24 gを吸収すると仮定し、揚げ油500 ml全部は含めていません。吸油量は変動します。</p><h3>参考資料</h3><ul><li><a href=\"https://www.okonomikitchen.com/egg-katsu/\">Okonomi Kitchen — egg katsu technique</a></li><li><a href=\"https://www.fda.gov/food/buy-store-serve-safe-food/what-you-need-know-about-egg-safety\">FDA — egg safety</a></li></ul>", "ingredients": [{"name": "卵（大、1個約50 g）", "amount": "4", "unit": "個"}, {"name": "パン粉（粗めのもの）", "amount": "80", "unit": "g"}, {"name": "揚げ用ひまわり油（大部分は鍋に残る）", "amount": "500", "unit": "ml"}, {"name": "キャベツ", "amount": "150", "unit": "g"}, {"name": "塩", "amount": "2", "unit": "g"}], "steps": [{"title": "作業台を準備する", "content": "キャベツを洗って水気を拭き、細切りにします。トレーに網を載せます。揚げる温度に対応するオーブン用ペーパーを、鍋に余裕をもって入る大きさに切ります。ワックスペーパーは使いません。", "image_url": "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/huevo-katsu/paso-01.webp", "image_alt": "作業台を準備する — 卵カツの作り方｜ゆでずに作るサクサクのパン粉衣"}, {"title": "パン粉に卵をのせる", "content": "浅い小鉢に紙を敷き、薄くパン粉を広げます。その上に卵をひとつ割り入れ、黄身を崩さないようにします。", "image_url": "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/huevo-katsu/paso-02.webp", "image_alt": "パン粉に卵をのせる — 卵カツの作り方｜ゆでずに作るサクサクのパン粉衣"}, {"title": "黄身を崩さず覆う", "content": "分量の塩から少量を振り、卵全体をパン粉でそっと覆います。用意したパン粉と塩を卵全体に配分し、黄身を押さえつけないでください。", "image_url": "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/huevo-katsu/paso-03.webp", "image_alt": "黄身を崩さず覆う — 卵カツの作り方｜ゆでずに作るサクサクのパン粉衣"}, {"title": "油を温める", "content": "直径約18 cmの小さく深い鍋に油を約2 cm入れ、170 °Cに温めます。温度計を使い、鍋の上部に余裕を残し、煙が出ないようにします。", "image_url": "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/huevo-katsu/paso-04.webp", "image_alt": "油を温める — 卵カツの作り方｜ゆでずに作るサクサクのパン粉衣"}, {"title": "静かに揚げ始める", "content": "長い穴あきお玉で紙を支え、油の近くから卵をゆっくり下ろします。紙は鍋の内側に収め、火から遠ざけます。表面に少量の熱い油をかけ、白身が固まるのを待ちます。", "image_url": "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/huevo-katsu/paso-05.webp", "image_alt": "静かに揚げ始める — 卵カツの作り方｜ゆでずに作るサクサクのパン粉衣"}, {"title": "紙を外して火を通す", "content": "卵がまとまったら長いトングで紙を外し、裏返します。合計約3〜4分を目安に火力を調節して揚げます。白身と黄身が固まるまで、必要なら弱めの火で続けます。", "image_url": "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/huevo-katsu/paso-06.webp", "image_alt": "紙を外して火を通す — 卵カツの作り方｜ゆでずに作るサクサクのパン粉衣"}, {"title": "油を切って繰り返す", "content": "網に上げます。残りもひとつずつ揚げ、その都度油を170 °Cに戻します。生卵に触れて加熱しなかったパン粉は捨てます。", "image_url": "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/huevo-katsu/paso-07.webp", "image_alt": "油を切って繰り返す — 卵カツの作り方｜ゆでずに作るサクサクのパン粉衣"}, {"title": "揚げたてを盛る", "content": "卵ごとにキャベツを添えます。慎重に切って中心まで火が通ったか確認し、衣がサクサクのうちに食べます。黄身が液状なら、提供前にさらに加熱します。", "image_url": "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/huevo-katsu/paso-08.webp", "image_alt": "揚げたてを盛る — 卵カツの作り方｜ゆでずに作るサクサクのパン粉衣"}], "category": "前菜・おつまみ", "course": "前菜", "cuisine": "日本風", "difficulty": "簡単", "prep_time_minutes": 10, "cook_time_minutes": 20, "total_time_minutes": 30, "servings": 4, "image_url": "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/huevo-katsu/portada.webp", "gallery": [{"url": "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/huevo-katsu/portada.webp", "alt": "白身と黄身まで火の通った黄金色の卵カツと細切りキャベツ"}], "video_urls": [], "keywords": ["卵カツ", "卵カツ 作り方", "生卵 パン粉 揚げ", "egg katsu"], "nutrition": {"calories": 212.9, "protein_g": 9.4, "carbs_g": 16.9, "fat_g": 11.9, "estimated": true, "serving_size": "卵カツ1個とキャベツの4分の1量", "note": "1人分の推定値です。使用する製品や出来上がり量によって変わります。", "source": "材料の一般的な栄養成分から算出した編集部による推定", "method": "Sum ingredient edible weights × generic per-100-g profiles; divide by recipe servings. See source JSON nutrition_calculation."}, "seo": {"title": "卵カツの作り方｜ゆでずに作るサクサクのパン粉衣", "description": "生卵をパン粉にのせて揚げる卵カツ。下ゆで不要で、衣の付け方と揚げ方を写真で紹介。黄身までしっかり火を通すレシピです。", "author": "Néstor Bastidas", "image_alt": "白身と黄身まで火の通った黄金色の卵カツと細切りキャベツ", "image_variants": ["https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/huevo-katsu/portada-1x1.webp", "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/huevo-katsu/portada-4x3.webp", "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/huevo-katsu/portada-16x9.webp"], "faq": [{"q": "卵を先にゆでますか？", "a": "いいえ。生卵をパン粉とオーブン用ペーパーにのせて覆い、慎重に揚げます。ゆで卵のフライではありません。"}, {"q": "黄身を半熟にできますか？", "a": "このレシピでは白身と黄身が固まるまで加熱します。黄身を生のまま残す短い加熱時間は案内していません。"}, {"q": "油全部を栄養計算に入れないのはなぜ？", "a": "500 mlは揚げるための油で、全量を食べるわけではありません。全体で24 g吸収するという目安で計算しています。"}], "additional_time_minutes": 0}, "published": false, "editorial_status": "draft"}, {"language": "pt", "slug": "ovo-katsu-panko", "public_path": "/pt/ovo-katsu-panko", "title": "Ovo katsu crocante com panko, passo a passo", "excerpt": "Faça ovo katsu com uma casquinha de panko sem cozinhar o ovo na água antes. Fotos do empanado e da fritura, com gema bem cozida.", "summary": "O ovo katsu é um ovo frito com uma crosta leve de panko. É montado cru sobre papel-manteiga próprio para a temperatura e frito um por vez, sem ferver nem congelar. Nesta versão, clara e gema ficam firmes. Rende 4 porções de aperitivo com repolho, em cerca de 30 minutos.", "content_html": "<h2>Sobre esta receita</h2><p>O ovo katsu é um ovo frito com uma crosta leve de panko. É montado cru sobre papel-manteiga próprio para a temperatura e frito um por vez, sem ferver nem congelar. Nesta versão, clara e gema ficam firmes. Rende 4 porções de aperitivo com repolho, em cerca de 30 minutos.</p>", "notes": "<h3>Dicas e conservação</h3><p>Use panela estável, utensílios secos e papel para assar adequado segundo o fabricante; mantenha-o longe de chamas. Nunca coloque água no óleo quente. O tempo inclui aquecimento e quatro frituras; o tamanho dos ovos influencia o ponto. Aqui clara e gema devem ficar firmes. Sirva imediatamente; refrigere sobras logo a 4 °C ou menos e reaqueça até 74 °C, embora percam crocância. Contém ovo e trigo. A nutrição estima 24 g de óleo absorvido no lote, não os 500 ml usados para fritar; a absorção real varia.</p><h3>Fontes</h3><ul><li><a href=\"https://www.okonomikitchen.com/egg-katsu/\">Okonomi Kitchen — egg katsu technique</a></li><li><a href=\"https://www.fda.gov/food/buy-store-serve-safe-food/what-you-need-know-about-egg-safety\">FDA — egg safety</a></li></ul>", "ingredients": [{"name": "ovos grandes, cerca de 50 g cada sem casca", "amount": "4", "unit": "unidades"}, {"name": "panko", "amount": "80", "unit": "g"}, {"name": "óleo de girassol para fritar; a maior parte fica na panela", "amount": "500", "unit": "ml"}, {"name": "repolho branco", "amount": "150", "unit": "g"}, {"name": "sal", "amount": "2", "unit": "g"}], "steps": [{"title": "Prepare a bancada", "content": "Lave, seque e fatie o repolho bem fino. Coloque uma grade sobre uma assadeira. Recorte papel para assar próprio para a temperatura de fritura, com folga dentro da panela. Não use papel encerado.", "image_url": "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/huevo-katsu/paso-01.webp", "image_alt": "Prepare a bancada — Ovo katsu crocante com panko, passo a passo"}, {"title": "Coloque o ovo sobre panko", "content": "Forre uma tigelinha rasa com um recorte de papel. Espalhe uma camada fina de panko e quebre um ovo sobre ela, mantendo a gema inteira.", "image_url": "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/huevo-katsu/paso-02.webp", "image_alt": "Coloque o ovo sobre panko — Ovo katsu crocante com panko, passo a passo"}, {"title": "Cubra sem romper a gema", "content": "Acrescente uma pitada do sal e cubra todo o ovo delicadamente com mais panko. Divida o panko e o sal disponíveis entre os ovos; não aperte a gema.", "image_url": "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/huevo-katsu/paso-03.webp", "image_alt": "Cubra sem romper a gema — Ovo katsu crocante com panko, passo a passo"}, {"title": "Aqueça o óleo", "content": "Aqueça o óleo a 170 °C numa panela pequena e funda de cerca de 18 cm, com aproximadamente 2 cm de profundidade. Use termômetro, deixe espaço livre e evite fumaça.", "image_url": "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/huevo-katsu/paso-04.webp", "image_alt": "Aqueça o óleo — Ovo katsu crocante com panko, passo a passo"}, {"title": "Comece a fritar", "content": "Apoie o papel numa escumadeira longa e baixe o ovo perto do óleo, devagar e sem respingar. Mantenha o papel dentro da panela, longe de chamas. Regue a superfície com um pouco de óleo quente até firmar.", "image_url": "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/huevo-katsu/paso-05.webp", "image_alt": "Comece a fritar — Ovo katsu crocante com panko, passo a passo"}, {"title": "Retire o papel e termine", "content": "Quando o ovo se sustentar, retire o papel com pinça longa e vire. Frite por cerca de 3–4 minutos no total, ajustando o fogo. Clara e gema devem ficar firmes; se necessário continue em fogo mais baixo.", "image_url": "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/huevo-katsu/paso-06.webp", "image_alt": "Retire o papel e termine — Ovo katsu crocante com panko, passo a passo"}, {"title": "Escorra e repita", "content": "Passe para a grade. Repita um ovo por vez, recuperando os 170 °C entre as frituras. Descarte o panko não cozido que tocou ovo cru.", "image_url": "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/huevo-katsu/paso-07.webp", "image_alt": "Escorra e repita — Ovo katsu crocante com panko, passo a passo"}, {"title": "Sirva na hora", "content": "Sirva cada ovo com parte do repolho. Corte com cuidado para conferir o centro e coma enquanto a crosta está crocante. Se a gema ainda estiver líquida, cozinhe mais antes de servir.", "image_url": "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/huevo-katsu/paso-08.webp", "image_alt": "Sirva na hora — Ovo katsu crocante com panko, passo a passo"}], "category": "Entradas e aperitivos", "course": "Entradas", "cuisine": "Inspiração japonesa", "difficulty": "Fácil", "prep_time_minutes": 10, "cook_time_minutes": 20, "total_time_minutes": 30, "servings": 4, "image_url": "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/huevo-katsu/portada.webp", "gallery": [{"url": "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/huevo-katsu/portada.webp", "alt": "Ovo katsu dourado cortado com clara e gema firmes ao lado de repolho fininho"}], "video_urls": [], "keywords": ["ovo katsu", "egg katsu", "ovo empanado panko", "tamago katsu"], "nutrition": {"calories": 212.9, "protein_g": 9.4, "carbs_g": 16.9, "fat_g": 11.9, "estimated": true, "serving_size": "1 ovo katsu com um quarto do repolho", "note": "Estimativa por porção; os produtos e o rendimento podem alterar os valores.", "source": "Cálculo editorial com perfis genéricos dos ingredientes", "method": "Sum ingredient edible weights × generic per-100-g profiles; divide by recipe servings. See source JSON nutrition_calculation."}, "seo": {"title": "Ovo katsu crocante com panko, passo a passo", "description": "Faça ovo katsu com uma casquinha de panko sem cozinhar o ovo na água antes. Fotos do empanado e da fritura, com gema bem cozida.", "author": "Néstor Bastidas", "image_alt": "Ovo katsu dourado cortado com clara e gema firmes ao lado de repolho fininho", "image_variants": ["https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/huevo-katsu/portada-1x1.webp", "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/huevo-katsu/portada-4x3.webp", "https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/huevo-katsu/portada-16x9.webp"], "faq": [{"q": "O ovo é cozido na água antes?", "a": "Não. O ovo cru vai sobre panko e papel para assar, é coberto e frito com cuidado. Não é ovo cozido empanado."}, {"q": "A gema pode ficar mole?", "a": "Nesta versão, clara e gema cozinham até ficarem firmes. Não indicamos fritura curta para deixar gema crua."}, {"q": "Por que não contar todo o óleo?", "a": "Os 500 ml são o meio de fritura e não são consumidos por completo. O cálculo considera 24 g absorvidos no lote, que podem variar."}], "additional_time_minutes": 0}, "published": false, "editorial_status": "draft"}]$payload$::jsonb;
foods jsonb := $foods$[{"slug": "panko", "name": "Panko", "description": "Pan rallado japonés en copos gruesos; normalmente contiene trigo."}]$foods$::jsonb;
aliases jsonb := $aliases$[{"slug": "huevo", "alias": "huevos grandes, aproximadamente 50 g sin cáscara cada uno"}, {"slug": "panko", "alias": "panko"}, {"slug": "aceite-de-girasol", "alias": "aceite de girasol para freír; la mayor parte queda en la sartén"}, {"slug": "repollo", "alias": "repollo blanco"}, {"slug": "sal", "alias": "sal"}]$aliases$::jsonb;
x jsonb; a jsonb; v public.recipes; made public.recipes; source_id uuid; group_id uuid;
BEGIN
PERFORM set_config('request.jwt.claim.sub','2caf0bab-d7e8-4d52-9910-d79799c27072',true);
IF NOT public.is_admin() THEN RAISE EXCEPTION 'Admin context missing'; END IF;
IF jsonb_array_length(payload)<>7 THEN RAISE EXCEPTION 'Need seven languages'; END IF;
IF EXISTS(SELECT 1 FROM public.recipes r JOIN jsonb_array_elements(payload) e ON r.public_path=e->>'public_path' OR (r.language=e->>'language' AND r.slug=e->>'slug')) THEN RAISE EXCEPTION 'Recipe URL already exists'; END IF;
IF EXISTS(SELECT 1 FROM public.content_pages p JOIN jsonb_array_elements(payload) e ON p.public_path=e->>'public_path') OR EXISTS(SELECT 1 FROM public.content_redirects r JOIN jsonb_array_elements(payload) e ON r.source_path=e->>'public_path') THEN RAISE EXCEPTION 'Route collision'; END IF;
FOR a IN SELECT value FROM jsonb_array_elements(foods) LOOP
 IF EXISTS(SELECT 1 FROM public.ingredients WHERE lower(name)=lower(a->>'name') AND slug<>a->>'slug' AND status='canonical') THEN RAISE EXCEPTION 'Canonical name collision'; END IF;
 INSERT INTO public.ingredients(slug,name,normalized_name,description,status,searchable,indexable)
 SELECT a->>'slug',a->>'name',lower(a->>'name'),a->>'description','canonical',true,false WHERE NOT EXISTS(SELECT 1 FROM public.ingredients WHERE slug=a->>'slug');
END LOOP;
FOR a IN SELECT value FROM jsonb_array_elements(aliases) LOOP
 IF NOT EXISTS(SELECT 1 FROM public.ingredients WHERE slug=a->>'slug' AND status='canonical') THEN RAISE EXCEPTION 'Missing canonical ingredient %',a; END IF;
 IF EXISTS(SELECT 1 FROM public.ingredient_aliases ia JOIN public.ingredients i ON i.id=ia.ingredient_id WHERE lower(trim(ia.alias))=lower(trim(a->>'alias')) AND i.slug<>a->>'slug' AND i.status='canonical') THEN RAISE EXCEPTION 'Alias collision %',a; END IF;
 INSERT INTO public.ingredient_aliases(ingredient_id,alias,normalized_alias) SELECT id,a->>'alias',lower(a->>'alias') FROM public.ingredients WHERE slug=a->>'slug' AND status='canonical' ON CONFLICT(ingredient_id,normalized_alias) DO NOTHING;
END LOOP;
FOR x IN SELECT value FROM jsonb_array_elements(payload) LOOP
 v:=jsonb_populate_record(NULL::public.recipes,x);
 IF v.language='es' THEN
  made:=public.create_recipe(v.language,v.slug,v.title,v.excerpt,v.ingredients,v.steps,v.category,v.prep_time_minutes,v.cook_time_minutes,v.servings,v.image_url,false,v.public_path);
  source_id:=made.id;group_id:=made.recipe_group_id;
 ELSE
  made:=public.create_recipe_translation(source_id,v.language,v.slug,v.title,v.excerpt,v.ingredients,v.steps,v.category,v.prep_time_minutes,v.cook_time_minutes,v.servings,v.image_url,false,v.public_path);
 END IF;
 UPDATE public.recipes SET content_html=v.content_html,summary=v.summary,notes=v.notes,difficulty=v.difficulty,course=v.course,cuisine=v.cuisine,total_time_minutes=v.total_time_minutes,keywords=v.keywords,nutrition=v.nutrition,gallery=v.gallery,video_urls=v.video_urls,seo=v.seo,editorial_status='ready',ready_at=now() WHERE id=made.id;
END LOOP;
IF (SELECT count(*) FROM public.recipes WHERE recipe_group_id=group_id)<>7 THEN RAISE EXCEPTION 'Incomplete group'; END IF;
IF (SELECT count(*) FROM public.recipe_ingredients WHERE recipe_id=source_id)<>5 OR EXISTS(SELECT 1 FROM public.recipe_ingredient_pending WHERE recipe_id=source_id) THEN RAISE EXCEPTION 'Unresolved ingredients'; END IF;
END $stage$;
SELECT id,recipe_group_id,language,slug,published,editorial_status FROM public.recipes WHERE public_path IN ('/huevo-katsu','/en/crispy-egg-katsu','/de/ei-katsu-panko','/fr/oeuf-katsu-panko','/it/uovo-katsu-panko','/ja/tamago-katsu-panko','/pt/ovo-katsu-panko') ORDER BY language;
